NEW_SKILL_GROUPS_3 = ['إدارة مشاريع', 'خدمة العملاء', 'ذكاء اصطناعي وأتمتة', 'جودة وسلامة']
NEW_SKILLS_3 = {
    'project-charter': ('ميثاق مشروع', 'وثيقة تأسيس تحدد هدف المشروع ونطاقه وصلاحياته قبل بدء العمل.', 'إدارة مشاريع',
        '## متى\nعند اعتماد مشروع جديد قبل تخصيص أي موارد له أو تعيين فريقه.\n\n## الخطوات\n1. اكتب غاية المشروع في جملة واحدة، والمشكلة التي يعالجها، والمستفيد منه.\n2. حدّد النطاق بقائمتين: ما يشمله المشروع وما لا يشمله، بما لا يقل عن ثلاثة بنود في كل قائمة.\n3. عرّف ثلاثة مؤشرات نجاح قابلة للقياس، ولكل مؤشر قيمته الحالية والمستهدفة وموعد قياسه.\n4. اذكر الراعي ومدير المشروع وصلاحياته في الميزانية والقرار بأرقام وحدود صريحة.\n5. ضع الافتراضات والقيود الرئيسة في جدول، ولكل بند أثره إن ثبت خطؤه.\n6. أرفق خانة اعتماد باسم الراعي وتاريخ التوقيع.\n\n## المخرج\nملف في `Docs/` باسم «ميثاق مشروع [اسم المشروع].md».\n\n## معيار القبول\nلا يُقبل ميثاق بلا نطاق مستبعد صريح، أو بلا مؤشرات نجاح مرقّمة وراعٍ مسمّى.\n'),
    'work-breakdown': ('هيكل تجزئة العمل', 'تفكيك نطاق المشروع إلى حزم عمل قابلة للتقدير والإسناد.', 'إدارة مشاريع',
        '## متى\nبعد اعتماد الميثاق وقبل وضع الجدول الزمني أو تقدير التكلفة.\n\n## الخطوات\n1. ابدأ من المخرجات النهائية المذكورة في الميثاق، لا من الأنشطة.\n2. فكّك كل مخرج إلى مستويات لا تتجاوز أربعة، بحيث تكون حزمة العمل الدنيا بين 8 و80 ساعة عمل.\n3. رقّم كل عنصر ترقيمًا هرميًا (1، 1.1، 1.1.1) واكتب له مخرجًا ملموسًا واحدًا.\n4. أسند لكل حزمة عمل مسؤولًا واحدًا وتقديرًا للجهد بالساعات.\n5. تحقق من قاعدة المئة: مجموع الحزم يغطي النطاق كله دون تداخل أو زيادة.\n6. راجع الهيكل مع منفذ واحد على الأقل من كل حزمة قبل اعتماده.\n\n## المخرج\nملف في `Docs/` باسم «هيكل تجزئة العمل [اسم المشروع].md» يتضمن جدولًا بالرمز والمخرج والمسؤول والجهد.\n\n## معيار القبول\nلا يُقبل هيكل فيه حزمة عمل بلا مسؤول أو بلا تقدير جهد، أو تتجاوز 80 ساعة.\n'),
    'risk-register': ('سجل المخاطر', 'سجل حيّ يرصد مخاطر المشروع ويرتبها ويعيّن مالكًا لكل خطر.', 'إدارة مشاريع',
        '## متى\nعند بدء المشروع، ثم يُحدَّث في كل تقرير حالة أو عند ظهور خطر جديد.\n\n## الخطوات\n1. اجمع المخاطر في جلسة لا تتجاوز ساعة مع ممثل عن كل حزمة عمل رئيسة.\n2. صِغ كل خطر بصيغة «إذا حدث [السبب] فإن [الأثر] على [الهدف]».\n3. قيّم الاحتمال والأثر على مقياس من 1 إلى 5، واحسب الدرجة بضربهما.\n4. رتّب المخاطر تنازليًا، وعالج كل خطر درجته 12 فأكثر بخطة استجابة مكتوبة.\n5. عيّن مالكًا واحدًا لكل خطر، وموعد المراجعة التالية، ومؤشرًا مبكرًا يدل على اقتراب وقوعه.\n6. أغلق الأخطار التي زال سببها مع ذكر تاريخ الإغلاق، ولا تحذفها.\n\n## المخرج\nملف في `Docs/` باسم «سجل المخاطر [اسم المشروع].md» بأعمدة: الرقم، الخطر، الاحتمال، الأثر، الدرجة، الاستجابة، المالك، الحالة.\n\n## معيار القبول\nلا يُقبل سجل فيه خطر درجته 12 فأكثر بلا خطة استجابة ومالك مسمّى.\n'),
    'milestone-plan': ('خطة المعالم', 'جدول زمني بالمعالم الرئيسة ومعايير إنجاز كل معلم.', 'إدارة مشاريع',
        '## متى\nبعد اكتمال هيكل تجزئة العمل وقبل الإعلان عن مواعيد التسليم لأصحاب المصلحة.\n\n## الخطوات\n1. استخرج من الهيكل ما بين 5 و12 معلمًا تمثل مخرجات مكتملة لا أنشطة جارية.\n2. اكتب لكل معلم معيار إنجاز يمكن التحقق منه بنعم أو لا.\n3. حدّد تاريخ الاستحقاق والمسؤول والمعالم السابقة التي يعتمد عليها.\n4. أضف احتياطيًا زمنيًا لا يقل عن 10% بين المعالم الحرجة، واذكره صراحة.\n5. علّم المعالم المرتبطة بالتزام خارجي أو تعاقدي بعلامة خاصة.\n6. اعرض الخطة على الراعي واعتمد الإصدار برقم وتاريخ.\n\n## المخرج\nملف في `Docs/` باسم «خطة المعالم [اسم المشروع].md» يتضمن جدولًا بالمعلم والمعيار والتاريخ والمسؤول والاعتمادية.\n\n## معيار القبول\nلا تُقبل خطة فيها معلم بلا معيار إنجاز قابل للتحقق، أو بلا تاريخ ومسؤول.\n'),
    'status-report': ('تقرير حالة أسبوعي', 'تقرير موجز يعرض وضع المشروع مقابل الخطة ويستدعي القرارات المطلوبة.', 'إدارة مشاريع',
        '## متى\nفي يوم ثابت من كل أسبوع طوال مدة التنفيذ، ويُرسل إلى الراعي وأصحاب المصلحة.\n\n## الخطوات\n1. ابدأ بحالة عامة بلون واحد (أخضر، أصفر، أحمر) مع سبب اللون في جملة.\n2. قارن الإنجاز الفعلي بالخطة في ثلاثة أبعاد: الزمن، والتكلفة، والنطاق، بنسب مئوية.\n3. اذكر ما أُنجز هذا الأسبوع وما سيُنجز في الأسبوع التالي في قائمتين لا تتجاوز كل منهما خمسة بنود.\n4. اعرض المخاطر والعوائق المفتوحة من سجل المخاطر مع مالك كل منها.\n5. اختم بالقرارات المطلوبة من المستلم، ولكل قرار موعد نهائي.\n6. التزم بصفحة واحدة لا تتجاوز 300 كلمة.\n\n## المخرج\nملف في `Docs/` باسم «تقرير حالة [اسم المشروع] الأسبوع [الرقم].md».\n\n## معيار القبول\nلا يُقبل تقرير بلا حالة لونية مبررة ونسب انحراف رقمية، أو يتجاوز صفحة واحدة.\n'),
    'retrospective': ('مراجعة نهاية مرحلة', 'جلسة منظمة تقيّم مرحلة منتهية وتخرج بإجراءات تحسين ملزمة.', 'إدارة مشاريع',
        '## متى\nخلال أسبوع من إغلاق كل مرحلة أو معلم رئيس، وقبل بدء المرحلة التالية.\n\n## الخطوات\n1. اجمع بيانات المرحلة قبل الجلسة: الزمن المخطط مقابل الفعلي، والتكلفة، وعدد طلبات التغيير.\n2. اعقد جلسة لا تتجاوز 90 دقيقة بحضور فريق التنفيذ كله ودون حضور الراعي.\n3. اطلب من كل مشارك ثلاثة بنود: ما نجح، وما تعثر، وما يجب تغييره.\n4. جمّع البنود في محاور، وصوّت لاختيار أهم ثلاثة محاور للمعالجة.\n5. حوّل كل محور إلى إجراء واحد بمسؤول وموعد، ولا تقبل إجراءً بلا مالك.\n6. راجع إجراءات المراجعة السابقة واذكر ما نُفذ منها وما لم يُنفذ.\n\n## المخرج\nملف في `Docs/QA/` باسم «مراجعة مرحلة [اسم المرحلة].md».\n\n## معيار القبول\nلا تُقبل مراجعة بلا بيانات رقمية للمرحلة، أو تخرج بأكثر من ثلاثة إجراءات أو بإجراء بلا مالك وموعد.\n'),
    'scope-change': ('طلب تغيير نطاق', 'نموذج رسمي لتوثيق تغيير مقترح على النطاق وتقدير أثره قبل اعتماده.', 'إدارة مشاريع',
        '## متى\nعند ورود أي طلب يضيف إلى نطاق المشروع المعتمد أو يحذف منه أو يغيّر مواعيده.\n\n## الخطوات\n1. اكتب التغيير المطلوب في جملة واحدة مع اسم طالبه وتاريخ الطلب.\n2. حدّد سبب الطلب ونتيجة رفضه، وهل هو إلزامي أم تحسيني.\n3. قدّر الأثر بأرقام على ثلاثة أبعاد: الأيام المضافة، والتكلفة بالريال، وحزم العمل المتأثرة.\n4. اعرض خيارين على الأقل: قبول التغيير كاملًا، أو قبوله جزئيًا، أو تأجيله إلى مرحلة لاحقة.\n5. اذكر الجهة المخولة بالاعتماد وفق حدود الصلاحية في الميثاق.\n6. سجّل القرار النهائي في سجل التغييرات بالرقم والتاريخ، وحدّث الخطة إن اعتُمد.\n\n## المخرج\nملف في `Docs/Decisions/` باسم «طلب تغيير [الرقم] [الموضوع].md».\n\n## معيار القبول\nلا يُقبل طلب بلا تقدير رقمي للأثر على الزمن والتكلفة، أو بلا جهة اعتماد مسمّاة.\n'),
    'lessons-learned': ('الدروس المستفادة', 'وثيقة إغلاق تجمع خلاصات المشروع لتُستثمر في المشاريع التالية.', 'إدارة مشاريع',
        '## متى\nعند إغلاق المشروع رسميًا، وخلال أسبوعين من تسليم آخر مخرج.\n\n## الخطوات\n1. اجمع مراجعات المراحل كلها وتقارير الحالة وسجل المخاطر وسجل التغييرات في مصدر واحد.\n2. قارن النتائج النهائية بمؤشرات الميثاق الثلاثة واذكر نسبة الانحراف لكل مؤشر.\n3. استخلص ما بين 5 و10 دروس، وصِغ كل درس بصيغة: الموقف، وما حدث، وما ينبغي فعله مستقبلًا.\n4. صنّف كل درس بمجال واحد: نطاق، أو زمن، أو تكلفة، أو جودة، أو تواصل، أو موردون.\n5. أجرِ مقابلة مع الراعي وثلاثة من أصحاب المصلحة لا تتجاوز 30 دقيقة لكل منها.\n6. حدّد لكل درس توصية قابلة للتطبيق ومن يتبناها في المشروع التالي.\n\n## المخرج\nملف في `Docs/` باسم «الدروس المستفادة [اسم المشروع].md».\n\n## معيار القبول\nلا تُقبل وثيقة بلا مقارنة رقمية بمؤشرات الميثاق، أو فيها درس بلا توصية ومجال محدد.\n'),
    'complaint-handling': ('معالجة شكوى', 'معالجة شكوى عميل من الاستلام إلى الإغلاق بردّ موثّق وإجراء تصحيحي.', 'خدمة العملاء',
        '## متى\nعند ورود شكوى عميل تتجاوز الحلّ الفوري وتحتاج تحقيقًا وردًّا مكتوبًا.\n\n## الخطوات\n1. سجّل الشكوى في سطر واحد: العميل، والقناة، والتاريخ، والمنتج أو الخدمة، وتصنيف الشدة (منخفضة، متوسطة، عالية).\n2. أرسل إقرار الاستلام خلال 4 ساعات عمل، وحدّد فيه موعد الردّ النهائي بما لا يتجاوز 3 أيام عمل.\n3. اجمع الوقائع من السجلات والأطراف المعنية، وميّز بين ما ثبت وما ادُّعي.\n4. حدّد السبب المباشر والسبب الجذري، واقترح تعويضًا أو تصحيحًا يتناسب مع الشدة.\n5. اكتب الردّ للعميل: اعتذار محدد، وما حدث، وما سيُفعل، وموعد التنفيذ، وجهة المتابعة.\n6. أغلق الشكوى بعد تأكيد العميل أو بعد 5 أيام عمل من الردّ دون اعتراض، وسجّل الدرس المستفاد.\n\n## المخرج\nملف في `Docs/QA/` باسم «شكوى [رقم الشكوى] [العميل].md».\n\n## معيار القبول\nلا تُقبل معالجة بلا سبب جذري مكتوب وردّ موثّق بتاريخه وإجراء تصحيحي له مسؤول وموعد.\n'),
    'service-level': ('اتفاقية مستوى الخدمة', 'صياغة اتفاقية مستوى خدمة بمؤشرات قابلة للقياس وحدود واضحة للالتزام.', 'خدمة العملاء',
        '## متى\nعند تحديد التزامات الدعم تجاه عميل أو إدارة داخلية قبل بدء تقديم الخدمة أو عند تجديدها.\n\n## الخطوات\n1. حدّد نطاق الخدمة في فقرة واحدة، وما يخرج عن النطاق صراحةً.\n2. صنّف الطلبات في أربعة مستويات أولوية، ولكل مستوى: زمن الاستجابة الأولى، وزمن الحلّ، وساعات التغطية.\n3. عرّف ثلاثة مؤشرات على الأقل: نسبة الالتزام بزمن الحلّ، ونسبة الحلّ من أول تواصل، ورضا العميل، مع هدف رقمي لكل مؤشر.\n4. اكتب آلية القياس: مصدر البيانات، ودورية التقرير (شهري)، ومن يراجعه.\n5. حدّد تبعات الإخلال والاستثناءات (الأعطال الخارجية، القوة القاهرة) وآلية التصعيد.\n6. أضف جدول مراجعة الاتفاقية كل 6 أشهر وأسماء الموقّعين.\n\n## المخرج\nملف في `Docs/` باسم «اتفاقية مستوى الخدمة [الخدمة].md».\n\n## معيار القبول\nلا تُقبل اتفاقية فيها مؤشر بلا هدف رقمي أو مستوى أولوية بلا زمن حلّ محدد.\n'),
    'faq-build': ('بناء الأسئلة الشائعة', 'بناء صفحة أسئلة شائعة من بيانات التذاكر الفعلية بإجابات قصيرة ومحدّثة.', 'خدمة العملاء',
        '## متى\nعند تكرار الأسئلة نفسها في قنوات الدعم أو قبل إطلاق منتج أو خدمة جديدة.\n\n## الخطوات\n1. استخرج تذاكر آخر 90 يومًا وصنّفها حسب الموضوع، واختر كل موضوع تكرر 10 مرات فأكثر.\n2. صِغ كل سؤال كما يطرحه العميل بكلماته، لا بمصطلحات الفريق.\n3. اكتب كل إجابة في 3 أسطر كحدّ أقصى، تبدأ بالحلّ مباشرة، ثم الشرط أو الاستثناء إن وجد.\n4. رتّب الأسئلة في مجموعات لا تتجاوز 7 أسئلة لكل مجموعة، والأكثر تكرارًا أولًا.\n5. اعرض المسودة على اثنين من فريق الدعم للتحقق من الدقة، وعلى عميل واحد لاختبار الوضوح.\n6. ثبّت تاريخ المراجعة وجدول تحديث كل 3 أشهر.\n\n## المخرج\nملف في `Docs/` باسم «الأسئلة الشائعة [المنتج].md».\n\n## معيار القبول\nلا تُقبل صفحة فيها سؤال لم يرد في التذاكر أو إجابة تتجاوز 3 أسطر أو بلا تاريخ مراجعة.\n'),
    'feedback-analysis': ('تحليل آراء العملاء', 'تحويل آراء العملاء النصية إلى موضوعات مرتبة بالتكرار والأثر مع توصيات.', 'خدمة العملاء',
        '## متى\nعند تراكم آراء العملاء من الاستبيانات والمراجعات والتذاكر دون تحليل منهجي.\n\n## الخطوات\n1. اجمع الآراء في جدول واحد بأعمدة: المصدر، والتاريخ، والنص، والتقييم إن وجد، بحد أدنى 100 رأي.\n2. صنّف كل رأي إلى موضوع واحد وشعور (إيجابي، سلبي، محايد)، واستخدم قائمة موضوعات لا تتجاوز 12 موضوعًا.\n3. احسب لكل موضوع: التكرار، ونسبة السلبي، والاتجاه مقارنة بالفترة السابقة.\n4. اختر أعلى 5 موضوعات سلبية تأثيرًا، وأرفق لكل موضوع اقتباسين حرفيين.\n5. اكتب لكل موضوع توصية واحدة قابلة للتنفيذ ومالكًا مقترحًا.\n\n## المخرج\nملف في `Outputs/` باسم «تحليل آراء العملاء [الفترة].md» مع جدول البيانات في `Data/`.\n\n## معيار القبول\nلا يُقبل تحليل بلا جدول مصدر وبلا تكرار رقمي لكل موضوع وبلا اقتباس حرفي يدعم كل استنتاج.\n'),
    'escalation-matrix': ('مصفوفة التصعيد', 'تحديد مستويات التصعيد ومسؤوليها وأزمنتها لحالات الدعم غير المحلولة.', 'خدمة العملاء',
        '## متى\nعند تأخر حلّ الحالات لغياب مسار تصعيد معلن أو عند تعدد الجهات المسؤولة.\n\n## الخطوات\n1. عرّف ثلاثة مستويات تصعيد: الخط الأول، والمشرف، والإدارة، ولكل مستوى اسم المسؤول وبديله.\n2. حدّد شرط التصعيد لكل مستوى: تجاوز زمن الحلّ، أو شدة الحالة، أو طلب العميل الصريح.\n3. ثبّت زمن الانتقال بين المستويات: 4 ساعات عمل للمستوى الثاني، و8 ساعات للمستوى الثالث.\n4. اكتب قناة التصعيد ومحتوى الرسالة الإلزامي: رقم الحالة، والعميل، والمحاولات السابقة، والمطلوب.\n5. أضف حالات التصعيد الفوري التي تتجاوز المستويات (توقف الخدمة الكامل، خطر قانوني).\n6. اختبر المصفوفة على 5 حالات سابقة وعدّلها بحسب النتائج.\n\n## المخرج\nملف في `Docs/` باسم «مصفوفة التصعيد [الخدمة].md».\n\n## معيار القبول\nلا تُقبل مصفوفة فيها مستوى بلا مسؤول مسمّى وبديل أو بلا زمن انتقال محدد بالساعات.\n'),
    'churn-review': ('مراجعة فقدان العملاء', 'تحليل العملاء المفقودين في فترة محددة وتحديد الأسباب القابلة للمعالجة.', 'خدمة العملاء',
        '## متى\nعند ارتفاع نسبة الإلغاء أو التوقف عن الشراء فوق الحد المتوقع أو عند المراجعة الربعية.\n\n## الخطوات\n1. عرّف العميل المفقود تعريفًا رقميًا (إلغاء الاشتراك أو انقطاع الشراء 90 يومًا) واحسب النسبة الشهرية لآخر 6 أشهر.\n2. استخرج قائمة المفقودين بأعمدة: تاريخ الانضمام، وتاريخ الفقد، والقيمة الشهرية، وعدد الشكاوى، وآخر تفاعل.\n3. قسّم المفقودين إلى شرائح بحسب مدة البقاء والقيمة، وحدّد الشريحة الأعلى خسارة.\n4. تواصل مع 10 عملاء مفقودين على الأقل من الشريحة الأعلى واستخرج السبب الرئيس لكل منهم.\n5. صنّف الأسباب إلى قابلة للمعالجة وغير قابلة، واحسب القيمة المعرضة للخطر لكل سبب.\n6. اقترح إجراءين للاحتفاظ بأعلى سببين قابلين للمعالجة، مع مؤشر نجاح وموعد قياس.\n\n## المخرج\nملف في `Outputs/` باسم «مراجعة فقدان العملاء [الفترة].md» مع قائمة المفقودين في `Data/`.\n\n## معيار القبول\nلا تُقبل مراجعة بلا نسبة فقد شهرية موثقة وبلا 10 مقابلات على الأقل وبلا قيمة مالية لكل سبب.\n'),
    'satisfaction-survey': ('استبيان رضا', 'تصميم استبيان رضا العملاء بعد الخدمة وتنفيذه وتحليل نتائجه.', 'خدمة العملاء',
        '## متى\nعند الحاجة إلى قياس رضا العملاء بعد التعامل مع الدعم أو بعد تسليم خدمة.\n\n## الخطوات\n1. حدّد هدف القياس ومؤشره: رضا العميل CSAT من 5، أو صافي الترويج NPS من 10، ولا تجمع بينهما في استبيان واحد.\n2. اكتب 5 أسئلة كحدّ أقصى: سؤال المؤشر أولًا، ثم سؤال مفتوح واحد عن السبب، ثم أسئلة الجوانب الفرعية.\n3. أرسل الاستبيان خلال 24 ساعة من إغلاق الحالة، واستهدف حجم عينة لا يقل عن 100 ردّ أو 30% من الحالات.\n4. اختبر الاستبيان على 5 عملاء قبل الإطلاق وعدّل أي سؤال فُهم بأكثر من معنى.\n5. حلّل النتائج حسب القناة والموظف ونوع الحالة، وصنّف الإجابات المفتوحة إلى موضوعات.\n6. اكتب 3 نتائج رئيسة وإجراءً واحدًا لأدنى جانب تقييمًا.\n\n## المخرج\nملف في `Outputs/` باسم «استبيان رضا [الخدمة] [الفترة].md» مع الردود الخام في `Data/`.\n\n## معيار القبول\nلا يُقبل استبيان يتجاوز 5 أسئلة أو تقرير بعينة دون 100 ردّ بلا تبرير مكتوب.\n'),
    'reply-templates': ('قوالب ردود الدعم', 'إعداد قوالب ردود موحدة لأكثر حالات الدعم تكرارًا مع حقول تخصيص إلزامية.', 'خدمة العملاء',
        '## متى\nعند تفاوت جودة الردود بين موظفي الدعم أو عند تكرار صياغة الردود نفسها يدويًا.\n\n## الخطوات\n1. اختر أعلى 15 حالة تكرارًا من تذاكر آخر 60 يومًا، وأعطِ كل حالة اسمًا ورمزًا فريدًا.\n2. اكتب لكل حالة قالبًا من 4 أجزاء: تحية باسم العميل، وإقرار بالمشكلة، والحلّ أو الخطوة التالية، وخاتمة بجهة المتابعة.\n3. ضع حقول التخصيص بين أقواس معقوفة مثل [اسم العميل] و[رقم الطلب]، ولا تُرسل القالب قبل تعبئتها كلها.\n4. التزم بحدّ 120 كلمة لكل قالب، وبنبرة رسمية واحدة لا تتغير بين القوالب.\n5. راجع القوالب مع مشرف الدعم ومسؤول العلامة، واعتمدها بتاريخ وإصدار.\n6. حدّد مالكًا للقوالب وجدول مراجعة كل 3 أشهر أو عند تغيّر السياسة.\n\n## المخرج\nملف في `Docs/` باسم «قوالب ردود الدعم [القناة].md».\n\n## معيار القبول\nلا يُقبل قالب يتجاوز 120 كلمة أو يخلو من حقل [اسم العميل] أو بلا رقم إصدار وتاريخ اعتماد.\n'),
    'prompt-spec': ('مواصفة أمر لنموذج لغوي', 'كتابة أمر موثّق لنموذج لغوي بمدخلات ومخرجات وقيود قابلة للاختبار.', 'ذكاء اصطناعي وأتمتة',
        '## متى\nعند الحاجة إلى أمر يُعاد استخدامه مع نموذج لغوي، لا أمر يُكتب مرة ويُنسى.\n\n## الخطوات\n1. اكتب هدف الأمر في جملة واحدة، وحدّد المستخدم الذي يشغّله والسياق الذي يعمل فيه.\n2. عرّف المدخلات المطلوبة واحدة واحدة: اسم كل مدخل، ونوعه، وهل هو إلزامي، ومثال واحد عليه.\n3. حدّد شكل المخرج بدقة: الصيغة (نص، جدول، JSON)، والطول الأقصى، واللغة، والحقول الإلزامية.\n4. اكتب القيود الصريحة: ما يُمنع على النموذج فعله، وكيف يتصرف عند نقص المدخلات أو تعارضها.\n5. أرفق ثلاث حالات اختبار على الأقل: مدخل، ومخرج متوقع، وحالة حدّية واحدة منها على الأقل.\n6. شغّل الأمر على الحالات الثلاث وسجّل النتيجة؛ عدّل الصياغة حتى تنجح الحالات كلها.\n\n## المخرج\nملف في `Docs/` باسم «مواصفة أمر [الموضوع].md».\n\n## معيار القبول\nلا تُقبل مواصفة بلا شكل مخرج محدد وثلاث حالات اختبار ناجحة موثّقة.'),
    'agent-evaluation': ('تقييم وكيل آلي', 'بناء مجموعة حالات اختبار لوكيل آلي وقياس نسبة نجاحه قبل الاعتماد.', 'ذكاء اصطناعي وأتمتة',
        '## متى\nقبل اعتماد وكيل آلي في عمل حقيقي، أو بعد أي تعديل جوهري في تعليماته أو أدواته.\n\n## الخطوات\n1. اكتب المهمة التي يُقاس عليها الوكيل في جملة واحدة، ومعيار النجاح لكل حالة (صواب الناتج، أو التزام الصيغة، أو زمن التنفيذ).\n2. ابنِ عشرين حالة اختبار على الأقل: نصفها حالات اعتيادية، وربعها حالات حدّية، وربعها مدخلات ناقصة أو مضللة.\n3. ثبّت لكل حالة: المدخل، والناتج المقبول، والسلوك الممنوع (مثل اختلاق بيانات أو تنفيذ إجراء بلا إذن).\n4. شغّل الوكيل على الحالات كلها ثلاث مرات لرصد التذبذب، وسجّل النتائج في جدول بأعمدة: رقم الحالة، النتيجة، سبب الفشل.\n5. احسب نسبة النجاح الكلية ونسبة النجاح في الحالات الحدّية منفصلتين، وصنّف أسباب الفشل في ثلاث فئات على الأكثر.\n6. اكتب التوصية: اعتماد، أو اعتماد مشروط بإشراف بشري، أو إعادة تصميم، مع أكثر ثلاث حالات فشل أثرًا.\n\n## المخرج\nملف في `Docs/QA/` باسم «تقييم وكيل [الموضوع].md» مع جدول الحالات في `Data/`.\n\n## معيار القبول\nلا يُقبل تقييم بأقل من عشرين حالة اختبار، أو بلا نسبة نجاح منفصلة للحالات الحدّية.'),
    'automation-candidate': ('ترشيح إجراء للأتمتة', 'تحديد ما إذا كان إجراء يدوي يستحق الأتمتة وبأي أداة وبأي عائد.', 'ذكاء اصطناعي وأتمتة',
        '## متى\nعند اقتراح أتمتة إجراء يدوي متكرر قبل إنفاق أي جهد في بنائه.\n\n## الخطوات\n1. صف الإجراء الحالي في خمس خطوات على الأكثر، مع تكراره الشهري والزمن المستغرق في كل تنفيذ.\n2. احسب التكلفة السنوية الحالية: عدد التنفيذات × الزمن × تكلفة الساعة، وأضف تكلفة الأخطاء المسجلة في آخر ثلاثة أشهر.\n3. قيّم القابلية للأتمتة في جدول بثلاثة معايير من 1 إلى 5: ثبات القواعد، وبنية المدخلات، وقلة الاستثناءات؛ لا يُرشَّح إجراء بمجموع أقل من 10.\n4. حدّد الأداة الأنسب (أداة أتمتة بلا كود، أو سكربت، أو وكيل بنموذج لغوي) مع سبب اختيارها واستبعاد البديلين.\n5. قدّر تكلفة البناء والصيانة السنوية، واحسب فترة الاسترداد بالأشهر.\n6. اكتب القرار: يُرشَّح، أو يُؤجَّل، أو يُستبعَد، مع الخطوة التالية ومالكها.\n\n## المخرج\nملف في `Docs/Decisions/` باسم «ترشيح أتمتة [الإجراء].md».\n\n## معيار القبول\nلا يُقبل ترشيح بلا تكلفة سنوية حالية محسوبة وفترة استرداد بالأشهر.'),
    'workflow-map': ('خريطة سير عمل', 'رسم سير عمل كامل بخطواته ومالكيه ونقاط انتقاله لكشف التأخير والتكرار.', 'ذكاء اصطناعي وأتمتة',
        '## متى\nعند تحليل سير عمل يمر بأكثر من شخص أو نظام ولا يوجد له رسم موثّق.\n\n## الخطوات\n1. حدّد حدث البداية وحدث النهاية لسير العمل في جملة واحدة لكل منهما.\n2. اجمع الخطوات من ثلاثة أشخاص على الأقل ينفذونها فعلًا، لا من وصف الإجراء الرسمي.\n3. سجّل كل خطوة في جدول بأعمدة: الرقم، الوصف، المنفّذ، النظام المستخدم، زمن التنفيذ، زمن الانتظار قبلها.\n4. ارسم الخريطة بصيغة Mermaid، وميّز نقاط الانتقال بين الأشخاص أو الأنظمة بلون أو شكل مختلف.\n5. احسب الزمن الكلي وزمن الانتظار الكلي، وعلّم كل خطوة انتظارها أطول من يوم عمل أو تتكرر مرتين.\n6. اختر ثلاث نقاط تحسين على الأكثر مرتبة بأثرها على الزمن الكلي.\n\n## المخرج\nملف في `Docs/` باسم «خريطة سير عمل [الموضوع].md» يضم الرسم والجدول.\n\n## معيار القبول\nلا تُقبل خريطة بلا زمن انتظار مسجّل لكل خطوة أو بلا نقاط انتقال مميّزة في الرسم.'),
    'ai-risk-check': ('فحص مخاطر استخدام الذكاء الاصطناعي', 'فحص منظّم لمخاطر إدخال نموذج ذكاء اصطناعي في مهمة قبل تشغيله.', 'ذكاء اصطناعي وأتمتة',
        '## متى\nقبل تشغيل نموذج ذكاء اصطناعي في مهمة تمس بيانات حقيقية أو قرارات تؤثر في أشخاص.\n\n## الخطوات\n1. صف الاستخدام المقترح في جملتين: ما يدخله المستخدم، وما يفعله النظام بالمخرج.\n2. صنّف البيانات المتداولة: عامة، أو داخلية، أو شخصية، أو سرية؛ وحدّد هل تُرسل إلى مزوّد خارجي.\n3. قيّم خمسة مخاطر في جدول: اختلاق المعلومات، وتسرب البيانات، والتحيز، والاعتماد المفرط، وغياب المساءلة؛ لكل خطر احتمال وأثر من 1 إلى 5.\n4. لكل خطر درجته (الاحتمال × الأثر) 12 فأكثر، اكتب إجراء تخفيف محددًا ومالكًا له.\n5. حدّد القرارات التي يُمنع فيها الاعتماد على المخرج دون مراجعة بشرية موثّقة.\n6. اكتب الحكم النهائي: مسموح، أو مسموح بشروط، أو ممنوع، مع موعد إعادة الفحص.\n\n## المخرج\nملف في `Docs/QA/` باسم «فحص مخاطر الذكاء الاصطناعي [الموضوع].md».\n\n## معيار القبول\nلا يُقبل فحص بلا تصنيف للبيانات وجدول للمخاطر الخمسة بدرجاتها وإجراءات التخفيف.'),
    'data-labeling-guide': ('دليل تصنيف بيانات', 'إعداد دليل تصنيف يضمن اتساق المصنّفين عند وسم البيانات لتدريب نموذج أو تقييمه.', 'ذكاء اصطناعي وأتمتة',
        '## متى\nعند الحاجة إلى وسم بيانات بأكثر من شخص، أو بنموذج ثم بمراجعة بشرية.\n\n## الخطوات\n1. اكتب غرض التصنيف وكيف سيُستخدم في جملة واحدة، وحدّد وحدة التصنيف (سطر، أو رسالة، أو صورة).\n2. عرّف كل فئة بتعريف صريح ومثالين إيجابيين ومثال سلبي قريب يسهل الخلط معه.\n3. اكتب قواعد الحسم للحالات الملتبسة، وأضف فئة «غير محدد» بشروط استخدامها.\n4. اختر عينة تجريبية من 50 عنصرًا وصنّفها باثنين من المصنّفين مستقلين، واحسب نسبة الاتفاق بينهما.\n5. راجع كل اختلاف، وعدّل التعريفات حتى تبلغ نسبة الاتفاق 85% فأكثر قبل بدء التصنيف الكامل.\n6. ثبّت صيغة ملف التصنيف: أعمدة المعرّف، والنص أو المرجع، والفئة، والمصنّف، والتاريخ.\n\n## المخرج\nملف في `Docs/` باسم «دليل تصنيف [الموضوع].md» مع العينة التجريبية في `Data/`.\n\n## معيار القبول\nلا يُقبل دليل بلا عينة تجريبية موثّقة ونسبة اتفاق بين مصنّفين لا تقل عن 85%.'),
    'human-in-loop': ('نقاط التدخل البشري', 'تحديد المواضع التي يجب أن يتوقف فيها النظام الآلي لمراجعة بشرية وكيفيتها.', 'ذكاء اصطناعي وأتمتة',
        '## متى\nعند تصميم إجراء آلي أو وكيل يتخذ قرارات أو ينفذ إجراءات لها أثر لا يُسترد بسهولة.\n\n## الخطوات\n1. اكتب خطوات الإجراء الآلي كلها في قائمة مرقّمة، وعلّم كل خطوة تنتج قرارًا أو تنفذ فعلًا خارج النظام.\n2. صنّف كل خطوة معلّمة بحسب قابلية الاسترداد: يُسترد خلال دقائق، أو يُسترد بتكلفة، أو لا يُسترد.\n3. ضع نقطة تدخل إلزامية عند كل خطوة لا تُسترد، أو تتجاوز حدًا ماليًا معلنًا، أو تمس بيانات شخصية.\n4. حدّد لكل نقطة: من يراجع، وما يراه، والمهلة القصوى للرد، وما يحدث عند انقضائها دون رد.\n5. اكتب شروط التصعيد الآلي: نسبة الثقة التي تحت 80%، أو الحالات الخارجة عن الأمثلة المعروفة.\n6. سجّل كل تدخل بشري في سجل بأعمدة: التاريخ، الخطوة، القرار، المراجع، السبب؛ وراجعه شهريًا لتقليص النقاط الزائدة.\n\n## المخرج\nملف في `Docs/` باسم «نقاط التدخل البشري [الإجراء].md».\n\n## معيار القبول\nلا يُقبل تصميم فيه خطوة لا تُسترد بلا نقطة تدخل بشري محددة المراجع والمهلة.'),
    'model-card': ('بطاقة تعريف نموذج', 'توثيق نموذج ذكاء اصطناعي مستخدم: غرضه وبياناته وأداؤه وحدوده في صفحة واحدة.', 'ذكاء اصطناعي وأتمتة',
        '## متى\nعند اعتماد نموذج ذكاء اصطناعي في عمل أو تسليمه لفريق آخر دون توثيق سابق.\n\n## الخطوات\n1. سجّل هوية النموذج: الاسم، والإصدار، والمزوّد، وتاريخ الاعتماد، والمالك المسؤول عنه داخليًا.\n2. اكتب الغرض المعتمد في جملة واحدة، وقائمة بثلاثة استخدامات ممنوعة على الأقل.\n3. وصف البيانات: مصدر بيانات التدريب أو الضبط إن عُرف، ونطاق البيانات التي اختُبر عليها داخليًا.\n4. سجّل الأداء في جدول: المقياس، والقيمة، وحجم عينة الاختبار الذي لا يقل عن 100 عنصر، وتاريخ القياس.\n5. اكتب الحدود المعروفة: اللغات أو الفئات التي يضعف فيها، وأنماط الأخطاء المتكررة التي رُصدت.\n6. حدّد موعد المراجعة الدورية (كل ستة أشهر على الأكثر) وشروط سحب الاعتماد.\n\n## المخرج\nملف في `Docs/` باسم «بطاقة نموذج [اسم النموذج].md».\n\n## معيار القبول\nلا تُقبل بطاقة بلا جدول أداء على عينة لا تقل عن 100 عنصر وقائمة استخدامات ممنوعة.'),
    'quality-checklist': ('قائمة فحص جودة', 'بناء قائمة فحص قصيرة تحكم على مخرج قبل تسليمه.', 'جودة وسلامة',
        '## متى\nعند وجود مخرج متكرر يُسلَّم لجهة أخرى وتتكرر فيه الأخطاء نفسها.\n\n## الخطوات\n1. اجمع آخر 10 حالات من المخرج، وسجّل كل ملاحظة أو إرجاع ورد عليها.\n2. حوّل الملاحظات إلى بنود فحص لا تتجاوز 12 بندًا، كل بند سؤال يُجاب عنه بنعم أو لا.\n3. رتّب البنود بترتيب الفحص الطبيعي: الاكتمال، ثم الصحة، ثم الصياغة والتنسيق.\n4. حدّد لكل بند: من يفحصه، وما الدليل المقبول، وهل البند حاسم يوقف التسليم أم ثانوي.\n5. جرّب القائمة على 3 حالات سابقة، واحذف كل بند لم يكشف خطأً واحدًا.\n6. ضع في رأس القائمة رقم الإصدار وتاريخه ومالكها.\n\n## المخرج\nملف في `Docs/QA/` باسم «قائمة فحص [المخرج].md».\n\n## معيار القبول\nلا تُقبل قائمة تتجاوز 12 بندًا أو تحتوي بندًا لا يُجاب عنه بنعم أو لا.\n'),
    'defect-root-cause': ('تحليل السبب الجذري لعيب جودة', 'تتبّع عيب جودة أو حادثة سلامة إلى سببه الجذري بالأدلة لا بالظن.', 'جودة وسلامة',
        '## متى\nعند تكرار عيب جودة أو حادثة سلامة أكثر من مرتين في شهر واحد رغم المعالجة الفورية.\n\n## الخطوات\n1. صف العيب في جملة واحدة بالأرقام: ما حدث، وأين، ومتى، وكم مرة، وما تكلفته.\n2. اجمع الأدلة قبل التحليل: السجلات، والصور، وإفادة شخصين على الأقل ممن باشروا الحالة.\n3. اسأل «لماذا» خمس مرات متتالية، وادعم كل إجابة بدليل مكتوب أو سجّلها فرضية.\n4. صنّف الأسباب في أربعة محاور: الإنسان، والطريقة، والمعدات، والمواد، واحكم على كل سبب بدليل.\n5. اختر السبب الجذري الواحد الذي لو أُزيل لما تكرر العيب، واكتب لماذا استُبعدت البدائل.\n6. حدّد إجراء الإزالة ومالكه وتاريخ التحقق بعد 30 يومًا.\n\n## المخرج\nملف في `Docs/QA/` باسم «سبب جذري [العيب].md».\n\n## معيار القبول\nلا يُقبل تحليل يقف عند سبب بشري أو يحوي «لماذا» بلا دليل أو فرضية مُعلَنة.\n'),
    'sop-write': ('كتابة إجراء تشغيل قياسي', 'توثيق مهمة متكررة في إجراء خطوة بخطوة ينفذه موظف جديد دون سؤال.', 'جودة وسلامة',
        '## متى\nعند مهمة تتكرر أسبوعيًا على الأقل، ويختلف تنفيذها باختلاف من يقوم بها.\n\n## الخطوات\n1. راقب التنفيذ الفعلي مرتين مع شخصين مختلفين، وسجّل كل اختلاف بينهما.\n2. اكتب الهدف والنطاق والمسؤول في ثلاثة أسطر في رأس الإجراء.\n3. قسّم المهمة إلى خطوات لا تتجاوز 15 خطوة، كل خطوة فعل أمر واحد بفاعل واحد.\n4. أضف عند كل خطوة حرجة: نقطة الفحص، والقيمة المقبولة، وما يُفعل عند الفشل.\n5. أرفق الأدوات والنماذج المطلوبة بمساراتها، وضع حدًا زمنيًا للإجراء كاملًا.\n6. سلّم الإجراء لشخص لم ينفذ المهمة قط، وعدّله حتى ينفذها دون سؤال واحد.\n\n## المخرج\nملف في `Docs/` باسم «إجراء [المهمة].md».\n\n## معيار القبول\nلا يُقبل إجراء لم يُجرَّب على منفّذ جديد أو يحوي خطوة بأكثر من فاعل.\n'),
    'safety-inspection': ('جولة تفتيش سلامة', 'تنفيذ جولة تفتيش ميدانية بقائمة ثابتة وتوثيق المخالفات بدرجة خطورتها.', 'جودة وسلامة',
        '## متى\nدوريًا كل أسبوع في موقع تشغيلي، أو فورًا بعد حادثة أو تغيير في المعدات.\n\n## الخطوات\n1. حدّد مسار الجولة ومناطقها، ولا تتجاوز 8 مناطق في الجولة الواحدة.\n2. استخدم قائمة فحص ثابتة لكل منطقة: المخارج، والحريق، والكهرباء، والمواد الخطرة، ومعدات الوقاية.\n3. وثّق كل مخالفة بصورة ومكان دقيق ودرجة خطورة: عالية تُعالج خلال 24 ساعة، متوسطة خلال 7 أيام، منخفضة خلال 30 يومًا.\n4. أوقف أي عمل عند مخالفة عالية الخطورة قبل إكمال الجولة.\n5. عيّن مسؤولًا وموعدًا لكل مخالفة، وأغلق مخالفات الجولة السابقة بالتحقق الميداني لا بالتصريح.\n\n## المخرج\nملف في `Docs/QA/` باسم «تفتيش سلامة [الموقع] [التاريخ].md».\n\n## معيار القبول\nلا يُقبل تقرير جولة فيه مخالفة بلا صورة أو درجة خطورة أو مسؤول وموعد إغلاق.\n'),
    'corrective-action': ('إجراء تصحيحي', 'صياغة إجراء تصحيحي يزيل سبب عدم المطابقة ويُتحقق من أثره.', 'جودة وسلامة',
        '## متى\nعند عدم مطابقة موثّقة من تدقيق، أو شكوى عميل، أو عيب متكرر بعد تحليل سببه.\n\n## الخطوات\n1. اكتب عدم المطابقة في جملة واحدة مع مرجعها: رقم التدقيق أو الشكوى وتاريخها.\n2. ميّز بين المعالجة الفورية للحالة والإجراء التصحيحي للسبب، واكتب كليهما.\n3. حدّد الإجراء التصحيحي: ماذا يتغير، ومن ينفذ، وبأي موعد لا يتجاوز 30 يومًا.\n4. ضع مؤشر تحقق رقميًا: عدد التكرارات في 60 يومًا بعد التنفيذ مقارنة بالفترة السابقة.\n5. راجع بعد الموعد: أغلق الإجراء إن انخفض التكرار إلى صفر، وإلا أعد تحليل السبب.\n\n## المخرج\nملف في `Docs/QA/` باسم «إجراء تصحيحي [المرجع].md».\n\n## معيار القبول\nلا يُقبل إجراء تصحيحي بلا سبب جذري مُحدَّد ومؤشر تحقق رقمي وموعد مراجعة.\n'),
    'process-audit': ('تدقيق إجراء', 'التحقق من أن إجراءً موثقًا يُنفَّذ فعليًا كما كُتب وتوثيق الفجوات.', 'جودة وسلامة',
        '## متى\nدوريًا كل ربع سنة لكل إجراء حرج، أو عند الشك في أن التنفيذ يخالف الوثيقة.\n\n## الخطوات\n1. اقرأ الإجراء الموثق واستخرج نقاط الفحص القابلة للتحقق، ولا تقل عن 5 نقاط.\n2. اختر عينة عشوائية من 10 حالات منفذة خلال آخر 90 يومًا، وافحص سجل كل حالة.\n3. قابل منفذَين اثنين على الأقل، واطلب منهما عرض التنفيذ لا وصفه.\n4. سجّل كل فجوة بتصنيف: مخالفة للوثيقة، أو نقص في الوثيقة، أو ممارسة أفضل غير موثقة.\n5. احسب نسبة المطابقة: الحالات المطابقة على العينة، واكتب الملاحظات مرتبة بالأثر.\n6. سلّم التقرير لمالك الإجراء، واطلب خطة إغلاق خلال 14 يومًا.\n\n## المخرج\nملف في `Docs/QA/` باسم «تدقيق إجراء [الإجراء].md».\n\n## معيار القبول\nلا يُقبل تدقيق بعينة أقل من 10 حالات أو بملاحظة بلا دليل موثق ومرجع حالة.\n'),
    'acceptance-criteria': ('صياغة معايير قبول', 'تحديد شروط قبول مخرج أو تسليم بصيغة قابلة للفحص قبل بدء العمل.', 'جودة وسلامة',
        '## متى\nقبل بدء أي عمل يُسلَّم لجهة أخرى، أو عند خلاف متكرر على ما إذا كان التسليم مكتملًا.\n\n## الخطوات\n1. اكتب المخرج المطلوب في جملة واحدة، ومن يقبله باسمه لا بصفته.\n2. اكتب من 3 إلى 8 معايير، كل معيار يبدأ بفعل فحص: «يحتوي»، «لا يتجاوز»، «يطابق»، «يعمل عند».\n3. أعطِ كل معيار قيمة قابلة للقياس: عددًا أو نسبة أو مدة أو مرجعًا يُقارن به.\n4. صنّف المعايير إلى إلزامية تُرفض بدونها ومرغوبة تُسجَّل كملاحظة.\n5. اعرض المعايير على الطرف القابل، واعتمدها بتوقيع أو رسالة قبل بدء العمل.\n\n## المخرج\nملف في `Docs/` باسم «معايير قبول [المخرج].md».\n\n## معيار القبول\nلا تُقبل معايير يحوي أحدها وصفًا غير مقيس مثل «جيد» أو «مناسب» أو «واضح».\n'),
    'workplace-5s': ('ترتيب موقع العمل بخمس خطوات', 'تنظيم موقع عمل بمنهجية الخطوات الخمس وتثبيت الترتيب بمعيار مكتوب.', 'جودة وسلامة',
        '## متى\nعند موقع عمل تُهدر فيه أكثر من 10 دقائق يوميًا في البحث عن أدوات أو مواد.\n\n## الخطوات\n1. الفرز: ضع بطاقة حمراء على كل عنصر لم يُستخدم خلال 30 يومًا، وأخرجه من الموقع خلال أسبوع.\n2. الترتيب: خصّص لكل عنصر باقٍ مكانًا ثابتًا مُعلَّمًا، بحيث لا يتجاوز الوصول إليه 30 ثانية.\n3. التنظيف: نظّف الموقع كاملًا، وسجّل كل عطل أو تلف يُكتشف أثناء التنظيف.\n4. التوحيد: صوّر الحالة المعيارية، وعلّق الصورة والقائمة اليومية للمحافظة عليها في الموقع.\n5. الانضباط: نفّذ فحصًا أسبوعيًا بخمسة بنود، وسجّل النتيجة من 25 درجة في سجل ظاهر.\n\n## المخرج\nملف في `Docs/QA/` باسم «ترتيب موقع [الموقع].md».\n\n## معيار القبول\nلا يُقبل تطبيق بلا صورة للحالة المعيارية وسجل فحص أسبوعي بدرجة مسجلة.\n'),
    'inventory-count': ('جرد مخزون', 'تنفيذ جرد فعلي للمخزون ومطابقته بالسجلات وتوثيق الفروقات.', 'عمليات',
        '## متى\nعند إغلاق فترة محاسبية، أو عند الاشتباه في فروقات بين الرصيد الدفتري والرصيد الفعلي.\n\n## الخطوات\n1. جمّد حركة المخزون قبل بدء العد، وصدّر الرصيد الدفتري لكل صنف بالأعمدة: الرمز، الاسم، الوحدة، الكمية الدفترية، الموقع.\n2. قسّم المواقع إلى مناطق عد، وعيّن لكل منطقة عادًّا ومراجعًا مستقلًا لا يرى نتيجة الآخر.\n3. أعد عد كل صنف يتجاوز فرقه 2% من الرصيد الدفتري أو 500 ريال من قيمته قبل اعتماد النتيجة.\n4. سجّل الفروقات النهائية في جدول بالأعمدة: الصنف، الدفتري، الفعلي، الفرق، القيمة، السبب المرجّح.\n5. صنّف أسباب الفروقات في فئات محددة: تلف، خطأ تسجيل، سرقة، خطأ عد، ثم اقترح إجراءً تصحيحيًا لكل فئة.\n6. ارفع قيد التسوية للاعتماد مع قائمة الأصناف التي تحتاج عدًّا دوريًا أكثر تكرارًا.\n\n## المخرج\nملف في `Docs/` باسم «تقرير جرد [الموقع] [الفترة].md» مع ورقة الفروقات في `Data/`.\n\n## معيار القبول\nلا يُقبل تقرير جرد بلا عدٍّ مزدوج للأصناف ذات الفروقات، أو بفروقات غير مصنّفة السبب.\n'),
    'demand-forecast': ('توقع الطلب', 'بناء توقع كمي للطلب من البيانات التاريخية مع قياس دقته.', 'بيانات',
        '## متى\nعند التخطيط للمشتريات أو الطاقة التشغيلية أو الميزانية لفترة قادمة بناءً على بيانات مبيعات أو استهلاك سابقة.\n\n## الخطوات\n1. اجمع سلسلة زمنية لا تقل عن 24 فترة متتالية بالأعمدة: التاريخ، الصنف أو الفئة، الكمية، وعلّم الفترات الشاذة مثل المواسم والإغلاقات.\n2. احسب المتوسط المتحرك لثلاث فترات، والنمو السنوي، ومعامل الموسمية لكل فترة من بيانات السنة الماضية على الأقل.\n3. ابنِ نموذجين على الأقل، أحدهما بسيط للمقارنة، واحتفظ بآخر 6 فترات للاختبار دون إدخالها في البناء.\n4. قس الدقة على فترات الاختبار بمتوسط الخطأ النسبي المطلق (MAPE)، واستبعد أي نموذج يتجاوز خطؤه 20%.\n5. قدّم التوقع في ثلاثة سيناريوهات: أساسي، ومتفائل، ومتحفظ، مع افتراض كل سيناريو في سطر واحد.\n6. حدّد موعد المراجعة التالية ومن يملك تحديث النموذج عند ورود بيانات جديدة.\n\n## المخرج\nملف في `Outputs/` باسم «توقع الطلب [الصنف] [الفترة].md» مع جدول التوقع في `Data/`.\n\n## معيار القبول\nلا يُقبل توقع بلا مقياس دقة محسوب على فترات اختبار مستقلة، أو بلا سيناريوهات ثلاثة معلنة الافتراضات.\n'),
    'pipeline-review': ('مراجعة خط المبيعات', 'مراجعة دورية لفرص البيع المفتوحة وتنظيفها وتقدير الإغلاق المتوقع.', 'تسويق ومبيعات',
        '## متى\nأسبوعيًا مع فريق المبيعات، أو قبل إعداد توقع الإيرادات لفترة قادمة.\n\n## الخطوات\n1. صدّر الفرص المفتوحة بالأعمدة: العميل، القيمة، المرحلة، تاريخ الإنشاء، تاريخ آخر نشاط، تاريخ الإغلاق المتوقع، المسؤول.\n2. علّم كل فرصة لم يسجَّل عليها نشاط منذ 30 يومًا أو مضى على تاريخ إغلاقها المتوقع، واطلب قرارًا فيها: تحديث أو إقفال.\n3. تحقق من اتساق المرحلة مع الدليل: لا تبقى فرصة في مرحلة «تفاوض» بلا عرض سعر موثق، ولا في «مؤهلة» بلا ميزانية وصاحب قرار معروفين.\n4. احسب القيمة المرجّحة لكل مرحلة بنسبة الإغلاق التاريخية للفريق لا بتقدير المسؤول، وقارنها بهدف الربع.\n5. حدّد أكبر 5 فرص بالقيمة، ولكل منها: العائق الحالي، والخطوة التالية، وموعدها، ومن يملكها.\n6. سجّل الفرص المقفلة هذا الأسبوع مع سبب الخسارة من قائمة محددة لا نص حر.\n\n## المخرج\nملف في `Docs/` باسم «مراجعة خط المبيعات [الأسبوع].md».\n\n## معيار القبول\nلا تُقبل مراجعة تبقي فرصة بلا نشاط لأكثر من 30 يومًا دون قرار، أو تحسب القيمة المرجّحة بتقدير شخصي.\n'),
    'cohort-analysis': ('تحليل الأفواج', 'تتبع سلوك مجموعات العملاء بحسب تاريخ انضمامهم لقياس الاحتفاظ والقيمة.', 'بيانات',
        '## متى\nعند الحاجة إلى معرفة ما إذا كان الاحتفاظ بالعملاء يتحسن أو يتراجع عبر الزمن، أو لقياس أثر تغيير في المنتج أو التسعير.\n\n## الخطوات\n1. عرّف الفوج بتاريخ أول عملية للعميل مجمّعًا شهريًا، وعرّف حدث العودة بدقة في جملة واحدة مثل «عملية شراء مدفوعة».\n2. حضّر جدولًا بالأعمدة: معرّف العميل، شهر الانضمام، شهر النشاط، وتأكد أن كل فوج يضم 50 عميلًا على الأقل وإلا فادمجه مع الفوج المجاور.\n3. ابنِ مصفوفة الاحتفاظ: الصفوف أفواج، والأعمدة الشهر 1 إلى 12 بعد الانضمام، والقيم نسبة العملاء النشطين.\n4. قارن الأفواج عند نقاط ثابتة: الشهر 1، والشهر 3، والشهر 6، وعلّم أي فوج ينحرف عن متوسط الأفواج السابقة بأكثر من 5 نقاط مئوية.\n5. اربط كل انحراف ملحوظ بحدث موثق بتاريخه مثل حملة أو تغيير سعر أو عطل، أو اكتب صراحة أن السبب غير معروف.\n6. اختم بثلاث نتائج قابلة للتنفيذ على الأكثر، ولكل نتيجة الفوج الذي تستند إليه.\n\n## المخرج\nملف في `Outputs/` باسم «تحليل الأفواج [المنتج] [الفترة].md» مع مصفوفة الاحتفاظ في `Data/`.\n\n## معيار القبول\nلا يُقبل تحليل بفوج يقل عن 50 عميلًا، أو بانحراف ملحوظ لم يُربط بحدث أو يُصرَّح بجهل سببه.\n'),
    'dashboard-spec': ('مواصفة لوحة مؤشرات', 'كتابة مواصفة كاملة للوحة مؤشرات قبل بنائها: المؤشرات والمصادر والتحديث والصلاحيات.', 'بيانات',
        '## متى\nقبل بناء أي لوحة مؤشرات لتحليل البيانات، أو عند طلب تعديل جوهري على لوحة قائمة.\n\n## الخطوات\n1. حدّد الجمهور والقرار الذي تخدمه اللوحة في جملة واحدة، واقصر المؤشرات الرئيسة على 6 على الأكثر في الصفحة الأولى.\n2. اكتب لكل مؤشر: الاسم، والمعادلة، والوحدة، والمصدر، وجدول البيانات وعموده، والاتجاه المرغوب، وحد التنبيه.\n3. حدّد مصادر البيانات ونمط التحديث لكل مصدر: يومي أو أسبوعي أو لحظي، والمسؤول عن جودته.\n4. ارسم تخطيط الصفحات: الصفحة الأولى للملخص، وصفحة لكل محور تحليل، مع عوامل التصفية المشتركة.\n5. حدّد الصلاحيات: من يرى كل صفحة، وأي صفوف تُقيَّد بحسب المستخدم.\n6. اكتب قائمة اختبارات القبول: مطابقة كل مؤشر بالمصدر الأصلي لعيّنة من 3 فترات، وزمن تحميل لا يتجاوز 5 ثوانٍ.\n\n## المخرج\nملف في `Docs/` باسم «مواصفة لوحة [الاسم].md».\n\n## معيار القبول\nلا تُقبل مواصفة بمؤشر بلا معادلة ومصدر محددين، أو بأكثر من 6 مؤشرات رئيسة في الصفحة الأولى.\n'),
    'data-quality-check': ('فحص جودة البيانات', 'فحص منهجي لمجموعة بيانات قبل استخدامها في تحليل أو تقرير.', 'بيانات',
        '## متى\nعند استلام مجموعة بيانات جديدة، أو قبل الاعتماد على بيانات في قرار أو تقرير تنفيذي.\n\n## الخطوات\n1. وثّق المصدر وتاريخ الاستخراج وعدد الصفوف والأعمدة، وقارن عدد الصفوف بالمتوقع من النظام الأصلي.\n2. افحص كل عمود على ستة أبعاد: الاكتمال، والتفرد، والنوع، والنطاق، والاتساق، والحداثة، وسجّل النتيجة في جدول.\n3. علّم كل عمود تتجاوز نسبة القيم المفقودة فيه 5%، وكل مفتاح مكرر، وكل قيمة خارج نطاقها المنطقي مثل تاريخ مستقبلي أو كمية سالبة.\n4. اختر عيّنة عشوائية من 30 صفًا وطابقها يدويًا بالمصدر الأصلي، وسجّل عدد الصفوف المطابقة.\n5. صنّف كل مشكلة: حرجة تمنع الاستخدام، أو متوسطة تحتاج تصحيحًا، أو منخفضة تُوثَّق فقط، مع الإجراء المقترح ومالكه.\n6. اكتب حكمًا نهائيًا في سطر واحد: صالحة للاستخدام، أو صالحة بشروط، أو غير صالحة.\n\n## المخرج\nملف في `Docs/QA/` باسم «فحص جودة [مجموعة البيانات].md».\n\n## معيار القبول\nلا يُقبل فحص بلا مطابقة عيّنة بالمصدر الأصلي، أو بلا حكم نهائي صريح على صلاحية البيانات.\n'),
    'procurement-rfq': ('طلب عروض أسعار', 'إعداد طلب عروض أسعار موحد للموردين ومقارنة العروض بمعايير معلنة.', 'عمليات',
        '## متى\nعند شراء يتجاوز حد الصلاحية المباشرة، أو عند تجديد عقد توريد يُشترط فيه التنافس.\n\n## الخطوات\n1. اكتب المواصفة الفنية للمطلوب: الكميات، والمواصفات، ومكان التسليم وموعده، وشروط الدفع، ومدة صلاحية العرض.\n2. أعلن معايير التقييم وأوزانها قبل الإرسال، مثل: السعر 50%، والجودة 25%، ومدة التسليم 15%، والضمان 10%.\n3. أرسل الطلب إلى 3 موردين مؤهلين على الأقل في اليوم نفسه، وبنموذج رد موحد يضمن قابلية المقارنة.\n4. حدّد موعدًا نهائيًا واحدًا لاستلام العروض، وارفض أي عرض يصل بعده أو يخالف نموذج الرد.\n5. قارن العروض في جدول بالمعايير المعلنة، واستبعد أي عرض يقل عن متوسط العروض بأكثر من 25% إلا بتبرير موثق.\n6. اكتب توصية الترسية في أول المذكرة مع السبب الحاسم، ومن يعتمدها.\n\n## المخرج\nملف في `Docs/Decisions/` باسم «طلب عروض أسعار [البند].md» مع جدول المقارنة في `Data/`.\n\n## معيار القبول\nلا يُقبل طلب بأقل من 3 موردين، أو بمعايير تقييم لم تُعلن قبل استلام العروض.\n'),
    'invoice-reconciliation': ('مطابقة الفواتير', 'مطابقة فواتير الموردين بأوامر الشراء وإيصالات الاستلام قبل الدفع.', 'مالية وتخطيط',
        '## متى\nقبل اعتماد أي دفعة لمورد، أو عند إغلاق الشهر لحصر الالتزامات غير المسددة.\n\n## الخطوات\n1. اجمع الفواتير المستلمة في جدول بالأعمدة: رقم الفاتورة، المورد، التاريخ، المبلغ، رقم أمر الشراء، رقم إيصال الاستلام.\n2. طابق كل فاتورة بأمر الشراء وإيصال الاستلام في ثلاثة أبعاد: الصنف، والكمية، وسعر الوحدة.\n3. اقبل تلقائيًا الفواتير التي لا يتجاوز فرقها 1% من قيمة أمر الشراء أو 100 ريال أيهما أقل، وأوقف ما عداها.\n4. افحص التكرار بمطابقة المورد والمبلغ والتاريخ ضمن 30 يومًا، وأوقف أي فاتورة بلا أمر شراء مسبق.\n5. سجّل الفواتير الموقوفة في جدول بالأعمدة: الفاتورة، نوع الفرق، المبلغ، المسؤول عن الحل، الموعد.\n6. أصدر قائمة الدفع المعتمدة مع إجمالي المبلغ وعدد الفواتير، وملخص الموقوف بحسب نوع الفرق.\n\n## المخرج\nملف في `Docs/` باسم «مطابقة فواتير [المورد أو الفترة].md» مع جدول المطابقة في `Data/`.\n\n## معيار القبول\nلا تُقبل قائمة دفع تضم فاتورة بلا مطابقة ثلاثية، أو فاتورة موقوفة بلا مسؤول وموعد حل.\n'),
    'board-deck': ('عرض لمجلس الإدارة', 'إعداد عرض موجز لمجلس الإدارة يبدأ بالقرار المطلوب ويختصر الأدلة.', 'عرض وإقناع',
        '## متى\nعند عرض نتائج أو طلب اعتماد أمام مجلس الإدارة أو لجنة عليا في وقت محدود.\n\n## الخطوات\n1. اكتب في الشريحة الأولى القرار أو الرسالة المطلوبة في جملة واحدة، وما يُطلب من المجلس تحديدًا.\n2. حدّد ثلاثة مؤشرات رئيسة لا أكثر، ولكل مؤشر: القيمة الحالية، والمستهدف، والاتجاه مقارنة بالفترة السابقة.\n3. اعرض المخاطر الثلاثة الأعلى مع احتمالها وأثرها وإجراء المعالجة لكل منها.\n4. خصّص شريحة واحدة للخيارات وشريحة واحدة للتوصية، ولا يتجاوز العرض اثنتي عشرة شريحة.\n5. انقل الجداول التفصيلية والمنهجية إلى ملحق منفصل لا يُعرض إلا عند السؤال.\n6. اكتب لكل شريحة عنوانًا يحمل خلاصتها في جملة كاملة، لا عنوانًا وصفيًا.\n\n## المخرج\nملف في `Outputs/` باسم «عرض مجلس الإدارة [الموضوع].md» يضم مخطط الشرائح والملحق.\n\n## معيار القبول\nلا يُقبل عرض لا يُعلن القرار المطلوب في شريحته الأولى أو يتجاوز اثنتي عشرة شريحة قبل الملحق.\n'),
    'meeting-minutes': ('محضر اجتماع', 'تحرير محضر اجتماع يثبّت القرارات والمهام والمسؤولين والمواعيد.', 'إدارة',
        '## متى\nبعد انتهاء أي اجتماع أُخذت فيه قرارات أو وُزّعت فيه مهام تحتاج متابعة.\n\n## الخطوات\n1. اكتب في الترويسة: موضوع الاجتماع، وتاريخه، والحاضرين، والمعتذرين، ومن تولّى التدوين.\n2. دوّن القرارات المتخذة في جدول بأعمدة: رقم القرار، ونص القرار، ومن اعتمده.\n3. دوّن المهام في جدول بأعمدة: المهمة، والمسؤول باسم واحد، وموعد التسليم بتاريخ محدد.\n4. سجّل النقاط المؤجلة والخلافات غير المحسومة في قسم مستقل مع من يملك حسمها.\n5. أرسل المحضر إلى الحاضرين خلال أربع وعشرين ساعة، واطلب التصويبات في مهلة يومي عمل.\n\n## المخرج\nملف في `Docs/` باسم «محضر اجتماع [الموضوع] [التاريخ].md».\n\n## معيار القبول\nلا يُقبل محضر فيه مهمة بلا مسؤول واحد مسمّى وموعد تسليم محدد.\n'),
    'proposal-write': ('كتابة عرض عمل', 'صياغة عرض عمل للعميل يربط مشكلته بالحل والنطاق والسعر والجدول.', 'عرض وإقناع',
        '## متى\nعند التقدم لعميل أو جهة بخدمة أو مشروع يحتاج موافقة مكتوبة على النطاق والتكلفة.\n\n## الخطوات\n1. اكتب في الصفحة الأولى فهمك لمشكلة العميل في ثلاث جمل، والنتيجة التي يشتريها لا الخدمة التي تبيعها.\n2. حدّد النطاق في قائمتين: ما يشمله العرض، وما لا يشمله صراحة.\n3. قسّم التنفيذ إلى مراحل لا تزيد على خمس، ولكل مرحلة: المخرجات، والمدة، ومعيار الاكتمال.\n4. اعرض السعر في جدول واحد مع شروط الدفع ومدة صلاحية العرض بتاريخ محدد.\n5. أضف الافتراضات التي يقوم عليها السعر، وما يتطلبه العرض من العميل من بيانات أو موافقات.\n6. اختم بخطوة القبول: من يوقّع، وماذا يحدث خلال أول أسبوع بعد التوقيع.\n\n## المخرج\nملف في `Docs/` باسم «عرض عمل [اسم العميل].md».\n\n## معيار القبول\nلا يُقبل عرض بلا قائمة استثناءات صريحة أو بلا تاريخ انتهاء لصلاحية السعر.\n'),
    'crisis-comms': ('بيان أزمة', 'إعداد بيان عاجل في حالة أزمة يثبت الوقائع ويحدد الإجراء وقناة التحديث.', 'محتوى',
        '## متى\nعند وقوع حادثة تمس العملاء أو السمعة أو العمليات وتستدعي ردًا علنيًا خلال ساعات.\n\n## الخطوات\n1. اجمع الوقائع المؤكدة فقط في قائمة، وافصلها عن التقديرات غير المؤكدة التي لا تُنشر.\n2. اكتب البيان في أربع فقرات: ما حدث، ومن تأثر، وما اتخذناه، وما سيأتي ومتى.\n3. التزم بما لا يزيد على مئتي كلمة، ولا تذكر سببًا لم يُثبت أو مسؤولية لم تُحسم.\n4. حدّد المتحدث الرسمي الوحيد باسمه، وقناة التحديثات، وموعد التحديث التالي بساعة محددة.\n5. أعدّ قائمة بخمسة أسئلة متوقعة من الإعلام أو العملاء وإجابة موحدة لكل منها.\n6. اعرض البيان على الجهة القانونية ومتخذ القرار قبل النشر، ووثّق من اعتمده ووقت الاعتماد.\n\n## المخرج\nملف في `Docs/` باسم «بيان أزمة [الموضوع] [التاريخ].md» يضم البيان وقائمة الأسئلة.\n\n## معيار القبول\nلا يُقبل بيان يتضمن واقعة غير مؤكدة أو يخلو من موعد التحديث التالي واسم المتحدث.\n'),
    'speech-outline': ('هيكل كلمة', 'بناء هيكل كلمة أو خطاب حول رسالة واحدة بزمن محسوب ونقاط انتقال واضحة.', 'عرض وإقناع',
        '## متى\nعند التحضير لإلقاء كلمة في فعالية أو افتتاح أو جلسة رسمية بوقت محدد سلفًا.\n\n## الخطوات\n1. اكتب الرسالة الواحدة التي يجب أن يخرج بها الحضور في جملة لا تزيد على خمس عشرة كلمة.\n2. حدّد زمن الكلمة بالدقائق، ووزّعه على: افتتاح لا يتجاوز عشرة بالمئة، وثلاث نقاط رئيسة، وخاتمة.\n3. اكتب لكل نقطة رئيسة: الفكرة، ودليلًا واحدًا أو قصة قصيرة، وجملة انتقال إلى النقطة التالية.\n4. احسب عدد الكلمات على أساس مئة وثلاثين كلمة في الدقيقة، واحذف ما يتجاوز الزمن.\n5. اكتب الجملة الافتتاحية والجملة الختامية كاملتين حرفيًا، واجعل الختام دعوة إلى فعل محدد.\n\n## المخرج\nملف في `Outputs/` باسم «هيكل كلمة [المناسبة].md».\n\n## معيار القبول\nلا يُقبل هيكل بلا رسالة واحدة معلنة في أوله أو يتجاوز عدد كلماته الزمن المحدد.\n'),
    'newsletter': ('نشرة دورية', 'إعداد عدد من نشرة دورية بأقسام ثابتة ومحتوى موجز ودعوة واحدة إلى فعل.', 'محتوى',
        '## متى\nعند إصدار عدد دوري لجمهور داخلي أو خارجي على فترة ثابتة أسبوعية أو شهرية.\n\n## الخطوات\n1. ثبّت أقسام النشرة في قالب لا يتغير بين الأعداد، بما لا يزيد على خمسة أقسام.\n2. اكتب عنوان العدد في أقل من خمسين حرفًا، وسطرًا تمهيديًا يذكر أهم خبر فيه.\n3. اكتب لكل قسم فقرة لا تتجاوز ثمانين كلمة ورابطًا واحدًا للتفاصيل عند الحاجة.\n4. ضع دعوة واحدة إلى فعل في العدد كله، في موضع ظاهر، بصيغة أمر واضحة.\n5. راجع الأسماء والأرقام والتواريخ مقابل مصدرها قبل الإرسال، وسجّل تاريخ الإرسال ونسبة الفتح في سجل الأعداد.\n\n## المخرج\nملف في `Outputs/` باسم «نشرة [الاسم] عدد [الرقم].md».\n\n## معيار القبول\nلا يُقبل عدد يتضمن أكثر من دعوة واحدة إلى فعل أو يتجاوز أي قسم فيه ثمانين كلمة.\n'),
    'policy-draft': ('صياغة سياسة داخلية', 'صياغة سياسة داخلية بنطاق وتعريفات وقواعد ومسؤوليات ومسار استثناء.', 'إدارة',
        '## متى\nعند الحاجة إلى تنظيم سلوك أو ممارسة متكررة داخل الجهة بقاعدة ملزمة ومعتمدة.\n\n## الخطوات\n1. اكتب الغرض من السياسة في جملة واحدة، ونطاقها: من تشمله، وما تستثنيه صراحة.\n2. عرّف المصطلحات الرئيسة في جدول قبل القواعد، بحيث لا يتجاوز عددها عشرة.\n3. اكتب القواعد مرقّمة، كل قاعدة في جملة واحدة ملزمة بصيغة «يجب» أو «يُحظر»، لا بصيغة التوصية.\n4. حدّد لكل قاعدة مسؤول التطبيق، ومسؤول الرقابة، ونتيجة المخالفة.\n5. أضف مسار طلب الاستثناء: من يطلب، ومن يعتمد، والمدة القصوى للرد بأيام العمل.\n6. ثبّت رقم الإصدار، وتاريخ السريان، وموعد المراجعة الدورية بما لا يتجاوز اثني عشر شهرًا.\n\n## المخرج\nملف في `Docs/` باسم «سياسة [الموضوع].md».\n\n## معيار القبول\nلا تُقبل سياسة فيها قاعدة بصيغة توصية أو بلا مسؤول تطبيق أو بلا مسار استثناء.\n'),
    'delegation-brief': ('تفويض مهمة', 'كتابة موجز تفويض يحدد النتيجة المطلوبة وحدود الصلاحية ونقاط المتابعة.', 'إدارة',
        '## متى\nعند إسناد مهمة أو مسؤولية إلى شخص آخر تتجاوز مدتها يومًا أو تتطلب قرارات باسمك.\n\n## الخطوات\n1. اكتب النتيجة المطلوبة في جملة واحدة، ومعيار نجاحها القابل للقياس، وموعد التسليم بتاريخ محدد.\n2. حدّد حدود الصلاحية: ما يقرره المفوَّض وحده، وما يعود إليك قبل تنفيذه، وسقف الإنفاق إن وُجد.\n3. اذكر الموارد المتاحة: الملفات، وجهات الاتصال، والأدوات، ومن يُستشار عند التعثر.\n4. حدّد نقاط المتابعة بتواريخ ثابتة لا تزيد على ثلاث، وما يُعرض في كل نقطة.\n5. اطلب من المفوَّض إعادة صياغة المهمة بكلماته في فقرة قبل البدء، واعتمدها أو صحّحها.\n\n## المخرج\nملف في `Docs/` باسم «تفويض [المهمة].md».\n\n## معيار القبول\nلا يُقبل تفويض بلا معيار نجاح قابل للقياس أو بلا حدود صلاحية مكتوبة صراحة.\n'),
}
